                view.copy_text(self.item.text)
            elif target.id == "edit":
                self._edit()
            elif target.id == "rewind":
                self._rewind()

    def text(self) -> str:
        return self.item.text

    def text_pos_at(self, x: int, y: int) -> Optional[int]:
