            return self.children[0].mt()
        return self.MT

    def mb(self) -> int:
        if self.head_h == 0 and self.children:
            return self.children[-1].mb()
        return self.MB

    def gap_for(self, i: int) -> int:
        if i <= 0:
            return 0 if self.children and self.children[0].LEAD else self.first_gap
        if i == 1 and self.children[0].LEAD:
