        return cur[0], cur[1]

    def _put(self, s: str) -> None:
        chars, states = self._cells()
        col = self.col or 0
        if col > len(chars):
            pad = col - len(chars)
            chars.extend(" " * pad)
            states.extend([""] * pad)
        end = col + len(s)
        chars[col:end] = s
        states[col:end] = [self.state] * len(s)
        self.col = end

    def _csi(self, params: str, final: str) -> None:
        if final == "m":
            self.state = _advance(self.state, params)
