        cl.addWidget(label("Recent", tone="faint", size="micro"), 0, Qt.AlignmentFlag.AlignTop)
        self.chips = Flow(6)
        cl.addWidget(self.chips, 1)
        sl.addWidget(self.chips_w)
        self.picker = Browser(self._browse_to, self._picked, native=self._pick_native)
