        self.options = Collapse(self._build_options, False)
        self.add(self.options)

        # ---- first message
        sec2 = QWidget()
        s2 = vbox(sec2, 8)
        s2.addWidget(_ns_label("First message"))
        self.prompt = text_area("", rows=2, name="First message")
