        self.custom_row = SetRow("Custom path", self.custom, fill=True)
        self.custom_row.setVisible(c.get("claudeBinary") not in PROGRAMS)
        self.add(self.custom_row)

        modes = modes_for(info)
        self.mode = combo(
            [(str(m["id"]), str(m["label"])) for m in modes],
