        """The notes bar: the review notes, added to the message or sent to Claude."""
        self.notes_bar = NotesBar()
        nl = QHBoxLayout(self.notes_bar)
        nl.setContentsMargins(12, 10, 12, 10)
        nl.setSpacing(8)
        self.notes_ico = QLabel()
