        bind(theme.theme.changed, self, lambda _t: self._on_config())
        self._on_config()
        self._on_ui()
        self._on_page()
        self.rebuild()

    # ---- top controls
    def _new_session(self) -> None:
        mods = self.new_btn.last_modifiers
        if mods & (Qt.KeyboardModifier.ShiftModifier | Qt.KeyboardModifier.AltModifier):
