def extract_answer(text: str, q: str) -> str:
    i = text.find(f'"{q}"="')
    if i < 0:
        return "Answered"
    rest = text[i + len(q) + 4 :]
    return rest[: rest.find('"')] if '"' in rest else rest


class Mark(QWidget):
    """`.ask-mark`: a radio ring or a checkbox square, filled with a check when chosen."""

