            nxt = [x for x in cur if x != label] if label in cur else cur + [label]
        else:
            nxt = [label]
            self.other[qi] = ""
            f = self.other_fields.get(qi)
            if f is not None and f.text():
                f.blockSignals(True)
                f.setText("")
                f.blockSignals(False)
