    try:
        info = json.loads((PILCROW_STATE / 'instance.json').read_text())
        os.kill(info['pid'], 0)
        h = hello(info['port'])
        if h.get('app') == 'pilcrow' and h.get('pid') == info['pid']:
            return {'pid': info['pid'], 'port': info['port'], 'url': f"http://127.0.0.1:{info['port']}/", 'version': h.get('version')}
    except Exception:
