  const type = cfg.type || (cfg.url ? (cfg.url.includes('/sse') ? 'sse' : 'http') : 'stdio');
  if (type === 'stdio') return { type, command: cfg.command || '', args: cfg.args || [], env: cfg.env || {} };
  return { type, url: cfg.url || '', headers: cfg.headers || {} };
