    const c = await git.commit(wt.path, { message });
    if (!c.ok && !NOTHING_TO_COMMIT.test(c.output || '')) throw new Error(c.output || 'commit failed');
    rec.commit = (await git.git(wt.path, ['rev-parse', '--short', 'HEAD'])).stdout.trim() || null;
