    status: failed && !done ? 'failed' : 'completed',
    reason: failed ? `${failed} of ${runs.length} did not finish` : null,
    summary: `${done} of ${runs.length} ${what}.\n${lines.join('\n')}`.slice(0, SUMMARY_MAX),
