import { lazy, Suspense, useEffect, useRef, useState, createContext, useContext } from 'react';
import { ChevronRight, File as FileIcon, Folder, FolderOpen, RefreshCw, X, Save, PanelLeft, Eye, EyeOff, ExternalLink, AtSign, BookOpen, PencilLine, Columns2, RotateCw } from 'lucide-react';
import { useStore, call, toast, confirmAction, insertIntoComposer, bumpFs, toasted, memo, takeFileOpen, type FilesState, type FileTab } from '../../lib/store';
import { folders, type DirEntry } from '../../lib/cache';
import { FileTouches, useFileHistory } from '../FileTouches';
import { Markdown } from '../Markdown';
import type { FileTouch, SessionSummary } from '../../lib/types';
import { basename, bytes, relPath, dirname } from '../../lib/format';
import { Spinner, Seg } from '../ui/bits';
import type { FileRead, FileWrite } from '../../lib/types';
import { errText } from '../../lib/format';
import { Empty, Loading } from '../ui/Empty';
import { useEvent } from '../ui/hooks';

// CodeMirror is most of a megabyte and only an open file needs it: it loads with the first one.
const Editor = lazy(() => import('./Editor').then((m) => ({ default: m.Editor })));


const HistoryCtx = createContext<{ cwd: string; map: Record<string, FileTouch[]> | null }>({ cwd: '', map: null });

export function FilesPanel({ session, cwd, visible }: { session: SessionSummary; cwd: string; visible: boolean }) {
  const fileOpen = useStore((s) => s.fileOpen);
  const history = useFileHistory(cwd);
  // Kept mounted while another tab is shown (RightPanel): hidden, it does not follow the stream at all.
  const rev = useStore((s) => (visible ? s.rt[session.id]?.rev || 0 : 0));
  const [st, setSt] = useState<FilesState>(() => memo(session.id).files || { tabs: [], active: null, expanded: { [cwd]: true }, showTree: true, showHidden: false });
  // Where the editor goes once the file is shown: a fresh object for each request, the same line or not.
  const [jump, setJump] = useState<{ line?: number } | null>(null);
  const [treeNonce, setTreeNonce] = useState(0);
  const update = useEvent((fn: (s: FilesState) => FilesState) =>
    setSt((s) => {
      const n = fn(s);
      memo(session.id).files = n;
      return n;
    }),
  );

  const openTab = useEvent(async (path: string, ln?: number) => {
    update((s) => (s.tabs.some((t) => t.path === path) ? { ...s, active: path } : { ...s, active: path, tabs: [...s.tabs, { path, doc: '', saved: '', loading: true }] }));
    setJump({ line: ln });
    const existing = (memo(session.id).files || st).tabs.find((t) => t.path === path);
    if (existing && !existing.loading && !existing.error) return;
    try {
      const r = await call<FileRead>('fs.read', { path }, { quiet: true });
      update((s) => ({ ...s, tabs: s.tabs.map((t) => (t.path === path ? { path, doc: r.text ?? '', saved: r.text ?? '', mtime: r.mtime, binary: r.binary, dataUrl: r.dataUrl, tooLarge: r.tooLarge, size: r.size } : t)) }));
      setJump({ line: ln });
    } catch (e) {
      update((s) => ({ ...s, tabs: s.tabs.map((t) => (t.path === path ? { ...t, loading: false, error: errText(e) } : t)) }));
    }
  });

  // A file asked for from elsewhere (a path in the conversation, a step's "Open in Files"): taken once.
  useEffect(() => {
    if (!fileOpen) return;
    takeFileOpen();
    openTab(fileOpen.path, fileOpen.line);
  }, [fileOpen, openTab]);

  // Pick up edits Claude makes to open files (only when there are no unsaved local edits). The tab
  // stays mounted when another one is chosen; hidden, it does nothing, and catches up once when shown.
  const checkedRev = useRef(-1);
  useEffect(() => {
    if (!visible || checkedRev.current === rev) return;
    const timer = setTimeout(async () => {
      checkedRev.current = rev;
      const cur = memo(session.id).files;
      if (!cur) return;
      for (const t of cur.tabs) {
        if (t.loading || t.binary || t.tooLarge || t.doc !== t.saved) continue;
        try {
          const r = await call<FileRead>('fs.read', { path: t.path }, { quiet: true });
          const text = r.text;
          if (r.mtime !== t.mtime && typeof text === 'string') update((s) => ({ ...s, tabs: s.tabs.map((x) => (x.path === t.path && x.doc === x.saved ? { ...x, doc: text, saved: text, mtime: r.mtime } : x)) }));
        } catch {
          /* file gone */
        }
      }
      setTreeNonce((n) => n + 1);
    }, 900);
    return () => clearTimeout(timer);
  }, [rev, cwd, visible, session.id, update]);

  const active = st.tabs.find((t) => t.path === st.active) || null;

  const save = async (tab: FileTab, force = false) => {
    const r = await call<FileWrite>('fs.write', { path: tab.path, text: tab.doc, expectedMtime: tab.mtime, force });
    if (r.conflict) {
      confirmAction({
        title: `${basename(tab.path)} changed on disk`,
        body: 'Someone (maybe Claude) changed this file after you opened it. Overwrite their version with yours?',
        confirm: 'Overwrite',
        danger: true,
        onConfirm: () => save(tab, true),
      });
      return;
    }
    update((s) => ({ ...s, tabs: s.tabs.map((t) => (t.path === tab.path ? { ...t, saved: tab.doc, mtime: r.mtime } : t)) }));
    toast(`Saved ${basename(tab.path)}`, 'success');
    bumpFs();
  };

  const close = (path: string) => {
    const tab = st.tabs.find((t) => t.path === path);
    const doClose = () =>
      update((s) => {
        const tabs = s.tabs.filter((t) => t.path !== path);
        return { ...s, tabs, active: s.active === path ? tabs[tabs.length - 1]?.path || null : s.active };
      });
    if (tab && tab.doc !== tab.saved) confirmAction({ title: `Discard unsaved changes to ${basename(path)}?`, confirm: 'Discard', danger: true, onConfirm: doClose });
    else doClose();
  };

  return (
    <div className="files">
      <div className="panel-toolbar">
        <button className={`icon-btn sm${st.showTree ? ' active' : ''}`} title="Toggle file tree" aria-label="Toggle file tree" onClick={() => update((s) => ({ ...s, showTree: !s.showTree }))}>
          <PanelLeft size={14} />
        </button>
        <span className="mono faint ellipsis grow" title={cwd}>
          {active ? relPath(active.path, cwd) : basename(cwd)}
        </span>
        {active && (
          <button className="icon-btn sm" title="Mention this file in the message" aria-label="Mention this file in the message" onClick={() => insertIntoComposer(session.id, `@${relPath(active.path, cwd)} `)}>
            <AtSign size={13} />
          </button>
        )}
        {active && isDoc(active.path) && !active.binary && !active.loading && (
          <Seg
            size="sm"
            className="doc-seg"
            label="Document view"
            value={docView(active)}
            onChange={(v) => update((s) => ({ ...s, showTree: v === 'split' ? false : s.showTree, tabs: s.tabs.map((t) => (t.path === active.path ? { ...t, view: v } : t)) }))}
            options={[
              { value: 'preview', label: <BookOpen size={13} />, title: docKind(active.path) === 'html' ? 'Preview' : 'Read' },
              { value: 'edit', label: <PencilLine size={13} />, title: 'Edit' },
              { value: 'split', label: <Columns2 size={13} />, title: 'Side by side' },
            ]}
          />
        )}
        {active && !active.binary && (
          <button className="icon-btn sm" title="Save (Ctrl+S)" aria-label="Save" disabled={active.doc === active.saved} onClick={() => save(active)}>
            <Save size={14} />
          </button>
        )}
        <button className="icon-btn sm" title={st.showHidden ? 'Hide dotfiles' : 'Show dotfiles'} aria-label={st.showHidden ? 'Hide dotfiles' : 'Show dotfiles'} onClick={() => update((s) => ({ ...s, showHidden: !s.showHidden }))}>
          {st.showHidden ? <Eye size={14} /> : <EyeOff size={14} />}
        </button>
        <button
          className="icon-btn sm"
          title="Refresh" aria-label="Refresh"
          onClick={() => {
            folders.dirs.clear();
            setTreeNonce((n) => n + 1);
          }}
        >
          <RefreshCw size={13} />
        </button>
      </div>
      <div className="files-body">
        {st.showTree && (
          <div className="tree">
            <HistoryCtx.Provider value={{ cwd, map: history }}>
              <TreeDir path={cwd} depth={0} st={st} update={update} onOpen={openTab} active={st.active} nonce={treeNonce} root />
            </HistoryCtx.Provider>
          </div>
        )}
        <div className="files-editor">
          {st.tabs.length > 0 && (
            <div className="ftabs">
              {st.tabs.map((t) => (
                <div key={t.path} className={`ftab${t.path === st.active ? ' on' : ''}`} title={t.path}>
                  <button className="ftab-main" onClick={() => update((s) => ({ ...s, active: t.path }))}>
                    {basename(t.path)}
                    {t.doc !== t.saved && <span className="dirty-dot" />}
                  </button>
                  <button className="ftab-x" onClick={() => close(t.path)} aria-label="Close tab">
                    <X size={11} />
                  </button>
                </div>
              ))}
            </div>
          )}
          {active ? (
            active.loading ? (
              <Loading label="Opening…" />
