                      key={active.path}
                      path={active.path}
                      doc={active.doc === active.saved ? active.saved : active.doc}
                      jump={jump}
                      onChange={(text) => update((s) => ({ ...s, tabs: s.tabs.map((t) => (t.path === active.path ? { ...t, doc: text } : t)) }))}
                      onSave={() => {
