              <div className="stat">
                <span className="stat-k">Output tokens</span>
                <span className="stat-v tnum">
                  <Num value={rt?.usage?.outputTokens || 0} format={tokens} />
                </span>
              </div>
            </div>
          </div>
        </div>
        {usage ? (
          <div className="ctx-cats">
