import { useRef, useState } from 'react';
import { RotateCw, ExternalLink, AppWindow, ArrowRight } from 'lucide-react';
import { useStore, models, call, memo } from '../../lib/store';
import type { SessionSummary } from '../../lib/types';
import type { ToolItem } from '../../lib/transcript';
import { Empty } from '../ui/Empty';

const LOCAL_URL = /https?:\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0|\[::1\])(?::\d+)?(?:\/[^\s'"<>)]*)?/g;
// What each command printed, read once per change of that command: the panel looks again with every
// streamed frame, and a long conversation has thousands of commands with long outputs.
const found = new WeakMap<ToolItem, { rev: number; urls: string[] }>();

function findUrls(sessionId: string): string[] {
  const m = models.get(sessionId);
  const out = new Set<string>();
  if (!m) return [];
  for (const t of m.tools.values()) {
    if (t.name !== 'Bash' && t.name !== 'PowerShell') continue;
    let hit = found.get(t);
    if (!hit || hit.rev !== t.rev) {
      const s = t.structured;
      const text = `${s?.stdout || ''}\n${s?.stderr || ''}\n${t.result?.text || ''}`;
      found.set(t, (hit = { rev: t.rev, urls: (text.match(LOCAL_URL) || []).map((u) => u.replace('0.0.0.0', 'localhost').replace(/[.,;]+$/, '')) }));
    }
    for (const u of hit.urls) out.add(u);
  }
  return [...out].slice(-6).reverse();
}

export function PreviewPanel({ session }: { session: SessionSummary }) {
  // Read again as the model changes (its rev); the panel draws only while its tab is shown.
  useStore((s) => s.rt[session.id]?.rev);
  const [url, setUrl] = useState(() => memo(session.id).preview);
  const [draft, setDraft] = useState(url || 'http://localhost:3000');
  const [nonce, setNonce] = useState(0);
  const frame = useRef<HTMLIFrameElement>(null);
  const detected = findUrls(session.id);

  const go = (u: string) => {
    let v = u.trim();
    if (!v) return;
    if (!/^https?:\/\//.test(v)) v = `http://${v}`;
    memo(session.id).preview = v;
    setUrl(v);
    setDraft(v);
    setNonce((n) => n + 1);
  };

  return (
    <div className="preview">
      <div className="panel-toolbar">
        <form
          className="url-bar"
          onSubmit={(e) => {
            e.preventDefault();
            go(draft);
          }}
        >
          <input aria-label="Address" className="input mono" value={draft} onChange={(e) => setDraft(e.target.value)} placeholder="http://localhost:3000" spellCheck={false} />
          <button className="icon-btn sm" type="submit" title="Open" aria-label="Open">
            <ArrowRight size={14} />
          </button>
        </form>
        <button className="icon-btn sm" title="Reload" aria-label="Reload" disabled={!url} onClick={() => setNonce((n) => n + 1)}>
          <RotateCw size={13} />
        </button>
        <button className="icon-btn sm" title="Open in your browser" aria-label="Open in your browser" disabled={!url} onClick={() => call('shell.openExternal', { url })}>
          <ExternalLink size={13} />
        </button>
      </div>
      {detected.length > 0 && (
        <div className="chips">
          {detected.map((u) => (
            <button key={u} className={`chip mono${u === url ? ' on' : ''}`} onClick={() => go(u)}>
              {u.replace(/^https?:\/\//, '')}
            </button>
          ))}
        </div>
      )}
      {url ? (
        <iframe key={nonce} ref={frame} className="preview-frame" src={url} title="App preview" sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-modals allow-downloads" />
      ) : (
        <Empty icon={AppWindow} title="Preview a local web app next to the conversation." hint="Ask Claude to start your dev server — addresses it prints show up above as shortcuts." />
      )}
    </div>
  );
}
