export function Keys({ combo, className = '' }: { combo: string; className?: string }) {
  const parts = combo === '+' ? ['+'] : combo.split(/\+(?!$)/);
  return (
    <span className={`keys ${className}`}>
      {parts.map((k, i) => (
        <kbd key={i}>{k}</kbd>
      ))}
    </span>
  );
}
