    ws.onmessage = (ev) => {
      // A response: { t: 'res', id, ok, r | e }. An event: { t: 'ev', e: name, d: payload }.
      let msg: Wire;
      try {
        msg = JSON.parse(ev.data);
      } catch {
        return;
      }
      if (msg.t === 'res' && typeof msg.id === 'number') {
        const p = this.pending.get(msg.id);
        if (!p) return;
        this.pending.delete(msg.id);
