  dispatch: { keys: 'Ctrl+Shift+D', label: 'Dispatch', run: () => (st().page === 'dispatch' ? showPage('session') : showDispatch(null)) },
  nextSession: {
    keys: 'Ctrl+Alt+↑ / ↓',
    label: 'Previous / next session',
    combos: ['Ctrl+Alt+ArrowUp', 'Ctrl+Alt+ArrowDown'],
