  }
}

function classifyResult(t: ToolItem, r: ToolResult): ToolStatus {
  const s = t.structured;
  if (s && typeof s === 'object') {
    if (s.isAsync || s.status === 'async_launched' || (s.backgroundTaskId && !r.isError)) return t.task && t.task.status !== 'running' ? (t.task.status === 'completed' ? 'done' : 'interrupted') : 'background';
  }
  if (!r.isError) return 'done';
  const txt = r.text || '';
  if (/interrupted by user/i.test(txt)) return 'interrupted';
  if (/doesn't want to proceed|user declined|was rejected|permission to use .* (has been|was) denied|not allowed/i.test(txt)) return 'denied';
  return 'error';
}

function assistantErrorText(code: string) {
  const map: Record<string, string> = {
    authentication_failed: 'Authentication failed — check the API key or gateway token Claude Code uses.',
    billing_error: 'The API account has a billing problem.',
    rate_limit: 'Rate limited by the API. Claude Code will retry.',
    overloaded: 'The API is overloaded right now.',
    invalid_request: 'The API rejected the request.',
    model_not_found: 'The selected model is not available through this endpoint.',
    server_error: 'The API returned a server error.',
    max_output_tokens: 'The response hit the output token limit.',
  };
  return map[code] || `Request failed (${code})`;
}

function summarizeServerResult(b: ContentBlock) {
  const c = b.content as string | ContentBlock[] | { error_code?: string } | undefined;
  if (Array.isArray(c)) return c.map((r) => (r.title ? `${r.title} — ${r.url}` : r.url || '')).filter(Boolean).join('\n');
  if (c && typeof c === 'object' && 'error_code' in c && c.error_code) return `Error: ${c.error_code}`;
  return typeof c === 'string' ? c : JSON.stringify(c, null, 2);
}

// ---------------------------------------------------------------- raw message shapes

/** The message body of a raw assistant/user message; the SDK sometimes sends a bare string. */
function messageOf(m: RawMsg): { id?: string; content?: string | ContentBlock[] } {
  if (!m.message) return {};
  if (typeof m.message === 'string') return { content: m.message };
  return m.message;
}

/** Content as blocks: a plain string is one text block. */
function blocksOf(content: string | ContentBlock[] | undefined): ContentBlock[] {
  if (Array.isArray(content)) return content;
  if (typeof content === 'string') return [{ type: 'text', text: content }];
  return [];
}

/** `origin` is an object on task notifications and a string elsewhere. */
function originKind(m: RawMsg): string | undefined {
  const o = m.origin as unknown;
  return o && typeof o === 'object' ? (o as { kind?: string }).kind : typeof o === 'string' ? o : undefined;
}

// ---------------------------------------------------------------- find

/** One place a search matched: the item, and which match within it (the k-th, in reading order). */
export interface FindHit {
  item: Item;
  k: number;
}

/**
 * The text Find reads in an item: what the row shows. The person's words; Claude's words and a slash
 * command's output through `plain` (the Markdown as it reads, not its source: no `**`, no link URLs);
 * a step's head (its verb and target, a line each) and its output; a notice. A question or a plan is
 * a form, not text, and a thought is folded away: neither is searched.
 */
export function findText(it: Item, plain: (md: string) => string = (s) => s, cwd?: string): string {
  switch (it.kind) {
    case 'user':
      return it.text || '';
    case 'text':
    case 'command-output':
      return it.text ? plain(it.text) : '';
    case 'notice':
      return it.text || '';
    case 'tool': {
      if (it.name === 'AskUserQuestion' || it.name === 'ExitPlanMode') return '';
      const m = toolMeta(it.name, it.input, cwd);
      // the head, then what the open card shows of the input (a command, a pattern), then the output
      const inp = (it.input || {}) as Record<string, unknown>;
      const shown = ['command', 'pattern', 'url', 'query'].map((k) => (typeof inp[k] === 'string' ? (inp[k] as string) : '')).filter((v) => v && v !== m.target);
      return [m.verb, m.target, ...shown, it.result?.text || ''].filter(Boolean).join('\n');
    }
    default:
      return '';
  }
}

// Each item's text lowered once per change of it, so a search per keystroke reads, never re-lowers.
// Keyed by the projection too: a caller passes one stable `textOf` (FindBar), so its reads are cached.
const lowered = new WeakMap<Item, { rev: number; status: string; fn: (it: Item) => string; text: string }>();

/**
 * Where `needle` occurs in the conversation, in order: the person's messages, Claude's words, the
 * steps (their heads and their output), notices and command output, as `textOf` reads them (findText
 * by default). What Find counts and steps through without drawing the conversation (FindBar); the
 * rows that are drawn correct these counts against what they show. At most `max` hits.
 */
const byDefault = (it: Item) => findText(it);
export function findInItems(items: Item[], needle: string, max = 3000, textOf: (it: Item) => string = byDefault): FindHit[] {
  const out: FindHit[] = [];
  const q = needle.toLocaleLowerCase();
  if (!q) return out;
  for (const it of items) {
    // a step's text changes with its status (the result arrives) as well as its rev
    const status = it.kind === 'tool' ? it.status : '';
    let c = lowered.get(it);
    if (!c || c.rev !== it.rev || c.status !== status || c.fn !== textOf) lowered.set(it, (c = { rev: it.rev, status, fn: textOf, text: textOf(it).toLocaleLowerCase() }));
    if (!c.text) continue;
    for (let i = c.text.indexOf(q), k = 0; i >= 0; i = c.text.indexOf(q, i + q.length), k++) {
      if (out.length >= max) return out;
      out.push({ item: it, k });
    }
  }
  return out;
}
