  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

a {
  color: var(--info);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
  text-underline-offset: 2px;
}

code,
pre,
kbd,
.mono {
  font-family: var(--font-mono);
  font-feature-settings: 'calt' 0, 'liga' 0;
  letter-spacing: 0;
}

svg {
  flex: none;
}

:focus {
