}

.muted {
  color: var(--text-2);
}
.faint {
  color: var(--text-3);
}
.grow {
  flex: 1;
  min-width: 0;
}
.row {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
}
.ellipsis {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}
.tnum {
  font-variant-numeric: tabular-nums;
}
.rot {
  transform: rotate(90deg);
}

/* ---- buttons
   Default buttons are quiet fills; one primary (amber) per surface. Every press gives a 2% squeeze. */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-1_5);
  height: 30px;
  padding: 0 var(--sp-3);
  border-radius: var(--r-2);
  background: var(--fill-2);
  color: var(--text);
