  color: var(--text-3);
}
.ovr-end {
  display: inline-flex;
  gap: var(--sp-2_5);
  font-size: var(--fs-micro);
  color: var(--text-3);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
