/* ================================================================ session
   The session on screen around the conversation: its header and crumbs, the folder picker, the
   fresh-session state, MCP notices, the find bar, and the narrow-window container queries. */

/* ================================================================ session */

.session {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.session-head {
  position: relative;
  container-type: inline-size;
  z-index: 2;
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  height: var(--header-h);
  padding: 0 var(--sp-2_5) 0 var(--sp-5);
  background: color-mix(in srgb, var(--canvas) 74%, transparent);
  -webkit-backdrop-filter: blur(22px) saturate(160%);
  backdrop-filter: blur(22px) saturate(160%);
}
.session-head.scrolled {
  box-shadow: 0 1px 0 var(--hair);
}
.session-title-wrap {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
}
.session-title {
  margin: 0;
  min-width: 0;
  flex: 0 1 auto;
  font-size: var(--fs-ui-plus);
  font-weight: 600;
  letter-spacing: -0.006em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: default;
}
.title-input {
  height: 28px;
  max-width: 420px;
  font-weight: 600;
}
.session-crumbs {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  min-width: 0;
  flex: 0 10 auto;
  color: var(--text-3);
  font-size: var(--fs-small);
  white-space: nowrap;
  overflow: hidden;
}
.crumb {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.crumb svg {
  opacity: 0.8;
}
.crumb.wt {
  color: var(--plan);
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1_75);
  flex: none;
  height: 22px;
  padding: 0 var(--sp-1);
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text-3);
}
.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.status-pill.requires_action {
  color: var(--accent-text);
  font-weight: 550;
}
.status-pill.error {
  color: var(--err);
}

.session-actions {
  display: flex;
  align-items: center;
  gap: var(--sp-0_5);
  flex: none;
}
.diffstat {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1_5);
  height: 26px;
  padding: 0 var(--sp-2_25);
  margin-right: var(--sp-1);
  border-radius: var(--r-pill);
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
}
.diffstat:hover,
.diffstat.on {
  background: var(--fill-2);
}

.session-error {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  margin: var(--sp-1) var(--sp-5) 0;
  padding: var(--sp-2) var(--sp-2) var(--sp-2) var(--sp-3_5);
  border-radius: var(--r-4);
  font-size: var(--fs-small);
  background: var(--err-wash);
  color: var(--err);
}

.session-empty {
  display: grid;
  justify-items: center;
  gap: var(--sp-2);
  padding: 12vh 0 var(--sp-6);
  text-align: center;
}
.session-empty-icon {
  margin-bottom: var(--sp-2);
}
.session-empty-title {
  font-size: var(--fs-display);
  font-weight: 560;
  letter-spacing: -0.02em;
}
.session-empty-git {
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  font-size: var(--fs-small);
}
.examples {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--sp-2);
  max-width: 560px;
  margin-top: var(--sp-5_5);
}
.example {
  height: 32px;
  padding: 0 var(--sp-3_5);
  border-radius: var(--r-7);
  font-size: var(--fs-ui);
  color: var(--text-2);
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
}
.example:hover {
  background: var(--fill-2);
  color: var(--text);
}

/* Narrow windows: the composer's mode chip keeps only its icon, and the header drops the folder and
   branch before it ever truncates the session title. */
@container (max-width: 420px) {
  .cbtn.mode .cbtn-label,
  .cbtn.mode .cbtn-chev {
    display: none;
  }
}
@container (max-width: 560px) {
  .session-crumbs {
    display: none;
  }
}

/* ================================================================ find in conversation */

.findbar {
  position: absolute;
  top: calc(var(--header-h) + 10px);
  right: 18px;
  z-index: var(--z-float);
  display: flex;
  align-items: center;
  gap: var(--sp-0_5);
  width: min(380px, calc(100% - 36px));
  height: 38px;
  padding: 0 var(--sp-1_25) 0 var(--sp-2_75);
  border-radius: 11px;
  background: var(--glass);
  -webkit-backdrop-filter: var(--glass-blur);
  backdrop-filter: var(--glass-blur);
  box-shadow: var(--shadow-glass);
}

.findbar-ico {
  color: var(--text-3);
  margin-right: var(--sp-1_5);
}
.findbar input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: none;
  outline: none;
  background: transparent;
  font-size: var(--fs-ui);
}
.findbar input::placeholder {
  color: var(--text-3);
}
.findbar-count {
  margin: 0 var(--sp-1_5);
  font-size: var(--fs-small);
  color: var(--text-3);
  white-space: nowrap;
}
.findbar-count.none {
  color: var(--err);
}
::highlight(find) {
  background-color: var(--find);
}
::highlight(find-current) {
  background-color: var(--accent-solid);
  color: var(--accent-ink);
}

/* folder crumb that is still a choice */
.crumb-btn {
  height: 22px;
  padding: 0 var(--sp-1_75) 0 var(--sp-1_5);
  margin-left: -6px;
  border-radius: var(--r-2);
  color: var(--text-2);
  cursor: pointer;
}
.crumb-btn:hover,
.crumb-btn.on {
  background: var(--fill-2);
  color: var(--text);
}
.crumb-chev {
  opacity: 0.7;
  margin-left: 1px;
}

/* folder picker (popover) */
.fpick {
  display: flex;
  flex-direction: column;
  min-height: 0;
  max-height: min(60vh, 460px);
}
.fpick-search {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  height: 36px;
  padding: 0 var(--sp-2_5) 0 var(--sp-3);
  border-bottom: 1px solid var(--hair);
  color: var(--text-3);
  cursor: text;
}
.fpick-search input {
  flex: 1;
  min-width: 0;
  background: none;
  border: 0;
  outline: 0;
  color: var(--text);
  font-size: var(--fs-ui);
}
.fpick-search input::placeholder {
  color: var(--text-3);
}
.fpick-list {
  padding: var(--sp-1_5);
  overflow-y: auto;
}
.fpick-row {
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-2_5);
  width: 100%;
  height: 34px;
  padding: 0 var(--sp-2);
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text);
}
.fpick-row:hover {
  background: var(--fill-2);
}
.fpick-row.on {
  grid-template-columns: 16px minmax(0, 1fr) auto 14px;
}
.fpick-ico {
  color: var(--text-3);
}
.fpick-name {
  font-size: var(--fs-ui);
}
.fpick-path {
  font-size: var(--fs-micro);
  color: var(--text-3);
  max-width: 160px;
}
/* on the hovered row's fill --text-3 falls short of 4.5:1, and of 3:1 for the icon (tokens.css) */
.fpick-row:hover .fpick-ico,
.fpick-row:hover .fpick-path {
  color: var(--text);
}
.fpick-check {
  color: var(--accent-text);
}
.fpick-empty {
  padding: var(--sp-3_5) var(--sp-2_5);
  font-size: var(--fs-small);
}
.fpick-foot {
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  padding: var(--sp-1_5) var(--sp-2);
  border-top: 1px solid var(--hair);
}
.fpick .browser {
  margin: 0;
  border: 0;
  border-radius: 0;
}
.fpick .browser-list {
  max-height: 240px;
}

/* fresh session: the folder is still a choice */
.session-empty-path {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  font-size: var(--fs-small);
}
.session-empty-change {
  font-size: var(--fs-small);
  color: var(--text-3);
}
.session-empty-change:hover {
  color: var(--accent-text);
}

/* ---------------------------------------------------------------- MCP attention, in the session */
.mcp-notice-stack {
  display: grid;
  gap: 1px;
}
.mcp-notice {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  min-height: 34px;
  padding: var(--sp-0_75) var(--sp-2_5) var(--sp-0_75) var(--sp-5);
  font-size: var(--fs-small);
  color: var(--text-2);
  background: var(--inset);
  box-shadow: inset 0 -0.5px 0 var(--hair);
}
.mcp-notice .btn {
  height: 26px;
  font-size: var(--fs-small);
}
.mcp-notice.auth > svg {
  color: var(--accent);
}
.mcp-notice.fail > svg {
  color: var(--err);
}
.mcp-notice-text {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mcp-notice-text b {
  font-weight: 600;
  color: var(--text);
}
.tool-fix {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-0_5) 0;
  font-size: var(--fs-small);
}
.mcp-auth {
  display: grid;
  gap: var(--sp-3);
}
.mcp-auth-line {
  display: flex;
  align-items: center;
  gap: var(--sp-2_25);
  font-size: var(--fs-ui);
